{"content":""""DepGraph dependency resolution engine."""

import base64
import binascii
import json
import os
import re
from typing import Dict, List


class DependencyConflictError(Exception):
    """Raised when version constraints cannot be satisfied."""


class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""


class PackageNotFoundError(Exception):
    """Raised when a required package is missing from the registry."""


_CONSTRAINT_RE = re.compile(r"^\s*(==|>=|<=|>|<)?\s*([A-Za-z0-9.\-_+]+)\s*$")


def _parse_version(version: str):
    """Parse a version string into a comparable tuple.

    Numeric components become ints, others stay strings. Trailing zeros
    are stripped so "1.0" equals "1.0.0".
    """
    parts = str(version).strip().split(".")
    parsed = []
    for part in parts:
        # Split leading numeric run from any suffix (e.g. "0rc1").
        m = re.match(r"^(\d+)(.*)$", part)
        if m:
            parsed.append(int(m.group(1)))
            if m.group(2):
                parsed.append(m.group(2))
        else:
            parsed.append(part)
    return tuple(parsed)


def _compare_versions(v1: str, v2: str) -> int:
    """Return -1, 0, 1 comparing two version strings numerically."""
    t1 = _parse_version(v1)
    t2 = _parse_version(v2)
    # Pad numeric-prefix comparison with zeros for different lengths.
    n = max(len(t1), len(t2))
    for i in range(n):
        a = t1[i] if i < len(t1) else 0
        b = t2[i] if i < len(t2) else 0
        if type(a) is not type(b):
            a, b = str(a), str(b)
        if a < b:
            return -1
        if a > b:
            return 1
    return 0


def _satisfies_one(version: str, operator: str, required: str) -> bool:
    cmp = _compare_versions(version, required)
    if operator == "==":
        return cmp == 0
    if operator == ">=":
        return cmp >= 0
    if operator == "<=":
        return cmp <= 0
    if operator == ">":
        return cmp > 0
    if operator == "<":
        return cmp < 0
    raise ValueError(f"Unknown operator: {operator}")


def satisfies(version: str, constraint: str) -> bool:
    """Check whether `version` satisfies a constraint string.

    Constraint may be empty/"*"/"any" (always true), a single comparison
    such as ">=1.0", a bare version (treated as ==), or comma-separated
    clauses such as ">=1.0,<3.0" (all must hold).
    """
    if constraint is None:
        return True
    text = str(constraint).strip()
    if text == "" or text == "*" or text.lower() == "any":
        return True
    clauses = [c.strip() for c in text.split(",") if c.strip() != ""]
    if not clauses:
        return True
    for clause in clauses:
        m = _CONSTRAINT_RE.match(clause)
        if not m:
            raise ValueError(f"Invalid version constraint: {clause!r}")
        operator = m.group(1) or "=="
        required = m.group(2)
        if not _satisfies_one(version, operator, required):
            return False
    return True


def _decode_manifest_text(raw_text: str, filename: str = "") -> dict:
    """Decode one manifest file's text into a manifest dict.

    Accepts raw JSON or base64-encoded JSON (the documented format), plus
    a JSON string wrapping base64 for robustness.
    """
    text = raw_text.strip()
    if not text:
        raise ValueError(f"Empty manifest: {filename}")
    # Raw JSON object: most lenient path.
    if text.startswith("{"):
        try:
            return json.loads(text)
        except json.JSONDecodeError:
            pass
    # Try base64 -> JSON.
    try:
        decoded = base64.b64decode(text, validate=True).decode("utf-8")
        return json.loads(decoded)
    except (binascii.Error, ValueError, json.JSONDecodeError):
        pass
    # Lenient base64 without validate (whitespace-tolerant).
    try:
        padded = text + "=" * (-len(text) % 4)
        decoded = base64.b64decode(padded).decode("utf-8")
        return json.loads(decoded)
    except (binascii.Error, ValueError, json.JSONDecodeError):
        pass
    # JSON string wrapping base64, e.g. "\"aGVsbG8=\"".
    try:
        inner = json.loads(text)
        if isinstance(inner, str):
            return _decode_manifest_text(inner, filename)
    except (json.JSONDecodeError, ValueError):
        pass
    raise ValueError(f"Cannot decode manifest: {filename}")


class DependencyResolver:
    """Resolve a dependency graph from a base64 manifest registry."""

    def __init__(self, registry_path: str):
        self.registry_path = registry_path
        self.registry: Dict[str, dict] = {}
        if not os.path.isdir(registry_path):
            raise FileNotFoundError(f"Registry directory not found: {registry_path}")
        for entry in sorted(os.listdir(registry_path)):
            full = os.path.join(registry_path, entry)
            if not os.path.isfile(full):
                continue
            if not entry.endswith(".manifest"):
                continue
            with open(full, "r", encoding="utf-8") as fh:
                raw = fh.read()
            manifest = _decode_manifest_text(raw, filename=entry)
            name = manifest.get("name") or entry[: -len(".manifest")]
            self.registry[name] = {
                "name": name,
                "version": str(manifest.get("version", "")),
                "dependencies": dict(manifest.get("dependencies") or {}),
            }

    @staticmethod
    def _extract_root_deps(root_config: dict) -> Dict[str, str]:
        """Extract {package: constraint} from a root config object."""
        if not isinstance(root_config, dict):
            raise ValueError("Root config must be a JSON object")
        if isinstance(root_config.get("dependencies"), dict):
            return {k: str(v) for k, v in root_config["dependencies"].items()}
        # Fallback: treat the whole object as a dep map unless it looks
        # like a package manifest itself (has name/version keys only).
        if "name" in root_config or "version" in root_config:
            deps = root_config.get("dependencies", {})
            if isinstance(deps, dict):
                return {k: str(v) for k, v in deps.items()}
            return {}
        return {k: str(v) for k, v in root_config.items()}

    def resolve(self, root_config_path: str) -> List[Dict]:
        """Compute a topologically sorted build order for the root config."""
        with open(root_config_path, "r", encoding="utf-8") as fh:
            root_config = json.load(fh)
        root_deps = self._extract_root_deps(root_config)

        constraints: Dict[str, List[str]] = {}
        # Seed constraints from the root config.
        for dep_name, dep_constraint in root_deps.items():
            constraints.setdefault(dep_name, []).append(dep_constraint)

        order: List[Dict] = []
        # 0 = unvisited, 1 = in stack, 2 = done.
        state: Dict[str, int] = {}

        def check_constraints(pkg_name: str):
            manifest = self.registry.get(pkg_name)
            if manifest is None:
                return
            for constraint in constraints.get(pkg_name, []):
                if not satisfies(manifest["version"], constraint):
                    raise DependencyConflictError(
                        f"Package {pkg_name} version {manifest['version']} "
                        f"does not satisfy constraint {constraint!r}"
                    )

        def visit(pkg_name: str, stack: List[str]):
            manifest = self.registry.get(pkg_name)
            if manifest is None:
                raise PackageNotFoundError(
                    f"Package not found in registry: {pkg_name}"
                )
            check_constraints(pkg_name)
            current = state.get(pkg_name, 0)
            if current == 2:
                return
            if current == 1:
                cycle = " -> ".join(stack + [pkg_name])
                raise CircularDependencyError(
                    f"Circular dependency detected: {cycle}"
                )
            state[pkg_name] = 1
            stack.append(pkg_name)
            for dep_name in sorted(manifest["dependencies"].keys()):
                dep_constraint = str(
                    manifest["dependencies"][dep_name]
                )
                constraints.setdefault(dep_name, []).append(dep_constraint)
                # A newly added constraint may conflict with an already
                # resolved package version.
                if state.get(dep_name, 0) == 2:
                    check_constraints(dep_name)
                visit(dep_name, stack)
            stack.pop()
            state[pkg_name] = 2
            order.append({"name": pkg_name, "version": manifest["version"]})

        for dep_name in sorted(root_deps.keys()):
            visit(dep_name, [])

        return order
