{"content":""""Required output tests for the DepGraph dependency resolver."""

import base64
import json
import os

import pytest

from resolver import (
    CircularDependencyError,
    DependencyConflictError,
    DependencyResolver,
    PackageNotFoundError,
)

LOCKFILE_PATH = "/app/lockfile.json"


def _encode_manifest(manifest: dict) -> str:
    return base64.b64encode(json.dumps(manifest).encode("utf-8")).decode("utf-8")


def _make_registry(tmp_path, manifests: dict):
    """Write {package_name: manifest_dict} as base64 .manifest files."""
    registry = tmp_path / "registry"
    registry.mkdir(exist_ok=True)
    for name, manifest in manifests.items():
        (registry / f"{name}.manifest").write_text(
            _encode_manifest(manifest), encoding="utf-8"
        )
    return str(registry)


def _make_root(tmp_path, dependencies: dict, extra: dict = None):
    root = dict(extra or {})
    root["dependencies"] = dependencies
    path = tmp_path / "root.json"
    path.write_text(json.dumps(root), encoding="utf-8")
    return str(path)


def _resolve(tmp_path, manifests: dict, root_deps: dict):
    registry_path = _make_registry(tmp_path, manifests)
    root_path = _make_root(tmp_path, root_deps)
    return DependencyResolver(registry_path).resolve(root_path)


def test_manifest_loading_and_decoding(tmp_path):
    manifests = {
        "alpha": {"name": "alpha", "version": "1.0.0", "dependencies": {}},
        "beta": {
            "name": "beta",
            "version": "2.3.4",
            "dependencies": {"alpha": ">=1.0"},
        },
    }
    registry_path = _make_registry(tmp_path, manifests)
    # Files on disk must be base64-encoded JSON.
    for name in manifests:
        raw = open(os.path.join(registry_path, f"{name}.manifest")).read().strip()
        decoded = json.loads(base64.b64decode(raw).decode("utf-8"))
        assert decoded == manifests[name]
    resolver = DependencyResolver(registry_path)
    assert set(resolver.registry.keys()) == {"alpha", "beta"}
    assert resolver.registry["beta"]["version"] == "2.3.4"
    assert resolver.registry["beta"]["dependencies"] == {"alpha": ">=1.0"}


def test_linear_dependency_chain(tmp_path):
    manifests = {
        "C": {"name": "C", "version": "1.0.0", "dependencies": {}},
        "B": {"name": "B", "version": "1.0.0", "dependencies": {"C": ">=1.0"}},
        "A": {"name": "A", "version": "1.0.0", "dependencies": {"B": ">=1.0"}},
    }
    result = _resolve(tmp_path, manifests, {"A": "==1.0.0"})
    names = [p["name"] for p in result]
    assert names == ["C", "B", "A"]


def test_complex_transitive_dependencies(tmp_path):
    manifests = {
        "leaf1": {"name": "leaf1", "version": "1.0.0", "dependencies": {}},
        "leaf2": {"name": "leaf2", "version": "1.0.0", "dependencies": {}},
        "mid1": {
            "name": "mid1",
            "version": "1.0.0",
            "dependencies": {"leaf1": ">=1.0", "leaf2": ">=1.0"},
        },
        "mid2": {
            "name": "mid2",
            "version": "1.0.0",
            "dependencies": {"leaf2": ">=1.0"},
        },
        "top": {
            "name": "top",
            "version": "1.0.0",
            "dependencies": {"mid1": ">=1.0", "mid2": ">=1.0"},
        },
    }
    result = _resolve(tmp_path, manifests, {"top": "==1.0.0"})
    names = [p["name"] for p in result]
    assert set(names) == {"top", "mid1", "mid2", "leaf1", "leaf2"}
    pos = {name: i for i, name in enumerate(names)}
    assert pos["leaf1"] < pos["mid1"] < pos["top"]
    assert pos["leaf2"] < pos["mid1"] < pos["top"]
    assert pos["leaf2"] < pos["mid2"] < pos["top"]


def test_diamond_dependency_compatibility(tmp_path):
    manifests = {
        "D": {"name": "D", "version": "1.5.0", "dependencies": {}},
        "B": {"name": "B", "version": "1.0.0", "dependencies": {"D": ">=1.0"}},
        "C": {"name": "C", "version": "1.0.0", "dependencies": {"D": "<2.0"}},
        "A": {
            "name": "A",
            "version": "1.0.0",
            "dependencies": {"B": ">=1.0", "C": ">=1.0"},
        },
    }
    result = _resolve(tmp_path, manifests, {"A": "==1.0.0"})
    names = [p["name"] for p in result]
    assert names.count("D") == 1
    pos = {name: i for i, name in enumerate(names)}
    assert pos["D"] < pos["B"]
    assert pos["D"] < pos["C"]
    assert pos["B"] < pos["A"]
    assert pos["C"] < pos["A"]


def test_version_constraint_logic(tmp_path):
    # >= satisfied.
    manifests = {"lib": {"name": "lib", "version": "2.0.0", "dependencies": {}}}
    assert [p["name"] for p in _resolve(tmp_path, manifests, {"lib": ">=1.0"})] == [
        "lib"
    ]
    # < violated -> conflict.
    with pytest.raises(DependencyConflictError):
        _resolve(tmp_path, manifests, {"lib": "<2.0"})
    # == satisfied / violated.
    assert _resolve(tmp_path, manifests, {"lib": "==2.0.0"})
    with pytest.raises(DependencyConflictError):
        _resolve(tmp_path, manifests, {"lib": "==1.0.0"})
    # > and <= boundaries.
    assert _resolve(tmp_path, manifests, {"lib": ">1.9.9"})
    with pytest.raises(DependencyConflictError):
        _resolve(tmp_path, manifests, {"lib": ">2.0.0"})
    assert _resolve(tmp_path, manifests, {"lib": "<=2.0.0"})
    with pytest.raises(DependencyConflictError):
        _resolve(tmp_path, manifests, {"lib": "<=1.9.9"})


def test_circular_dependency_detection(tmp_path):
    # Direct self-cycle A -> A.
    with pytest.raises(CircularDependencyError):
        _resolve(
            tmp_path,
            {"A": {"name": "A", "version": "1.0.0", "dependencies": {"A": ">=1.0"}}},
            {"A": "==1.0.0"},
        )
    # Indirect cycle A -> B -> A.
    with pytest.raises(CircularDependencyError):
        _resolve(
            tmp_path,
            {
                "A": {
                    "name": "A",
                    "version": "1.0.0",
                    "dependencies": {"B": ">=1.0"},
                },
                "B": {
                    "name": "B",
                    "version": "1.0.0",
                    "dependencies": {"A": ">=1.0"},
                },
            },
            {"A": "==1.0.0"},
        )


def test_version_conflict_detection(tmp_path):
    manifests = {
        "B": {"name": "B", "version": "1.0.0", "dependencies": {}},
        "A": {"name": "A", "version": "1.0.0", "dependencies": {"B": ">=2.0"}},
        "C": {"name": "C", "version": "1.0.0", "dependencies": {"B": "<1.5"}},
    }
    registry_path = _make_registry(tmp_path, manifests)
    root_path = _make_root(tmp_path, {"A": "==1.0.0", "C": "==1.0.0"})
    with pytest.raises(DependencyConflictError):
        DependencyResolver(registry_path).resolve(root_path)


def test_missing_package_handling(tmp_path):
    manifests = {
        "A": {
            "name": "A",
            "version": "1.0.0",
            "dependencies": {"ghost": ">=1.0"},
        }
    }
    with pytest.raises(PackageNotFoundError):
        _resolve(tmp_path, manifests, {"A": "==1.0.0"})


def test_topological_sort_order(tmp_path):
    manifests = {
        "D": {"name": "D", "version": "1.0.0", "dependencies": {}},
        "C": {"name": "C", "version": "1.0.0", "dependencies": {"D": ">=1.0"}},
        "B": {"name": "B", "version": "1.0.0", "dependencies": {"D": ">=1.0"}},
        "A": {
            "name": "A",
            "version": "1.0.0",
            "dependencies": {"B": ">=1.0", "C": ">=1.0"},
        },
    }
    registry_path = _make_registry(tmp_path, manifests)
    root_path = _make_root(tmp_path, {"A": "==1.0.0"})
    resolver = DependencyResolver(registry_path)
    result = resolver.resolve(root_path)
    pos = {p["name"]: i for i, p in enumerate(result)}
    for name, manifest in resolver.registry.items():
        if name not in pos:
            continue
        for dep in manifest["dependencies"]:
            assert dep in pos, f"dependency {dep} missing from output"
            assert pos[dep] < pos[name], (
                f"dependency {dep} must precede dependent {name}"
            )


def test_lockfile_output_format():
    assert os.path.exists(LOCKFILE_PATH), f"{LOCKFILE_PATH} not found"
    with open(LOCKFILE_PATH, encoding="utf-8") as fh:
        data = json.load(fh)
    assert isinstance(data, list), "lockfile must be a JSON list"
    assert len(data) > 0, "lockfile must not be empty"
    for entry in data:
        assert isinstance(entry, dict), "each lockfile entry must be an object"
        assert set(entry.keys()) == {"name", "version"}, (
            f"entry must have exactly name/version keys, got {sorted(entry.keys())}"
        )
        assert isinstance(entry["name"], str) and entry["name"]
        assert isinstance(entry["version"], str) and entry["version"]


def test_empty_dependencies(tmp_path):
    registry_path = _make_registry(tmp_path, {})
    root_path = _make_root(tmp_path, {})
    assert DependencyResolver(registry_path).resolve(root_path) == []


def test_self_dependency_error(tmp_path):
    manifests = {
        "A": {"name": "A", "version": "1.0.0", "dependencies": {"A": ">=1.0"}}
    }
    with pytest.raises(CircularDependencyError):
        _resolve(tmp_path, manifests, {"A": "==1.0.0"})


def test_multiple_constraints_intersection(tmp_path):
    manifests = {
        "lib": {"name": "lib", "version": "2.0.0", "dependencies": {}},
        "P": {"name": "P", "version": "1.0.0", "dependencies": {"lib": ">1.0"}},
        "Q": {"name": "Q", "version": "1.0.0", "dependencies": {"lib": "<3.0"}},
    }
    result = _resolve(tmp_path, manifests, {"P": "==1.0.0", "Q": "==1.0.0"})
    entry = next(p for p in result if p["name"] == "lib")
    assert entry["version"] == "2.0.0"
    # Conflicting intersection must fail: no 2.0.0 satisfies <1.5 and >1.0
    # combined with a second constraint set that excludes 2.0.0.
    manifests2 = {
        "lib": {"name": "lib", "version": "2.0.0", "dependencies": {}},
        "P": {"name": "P", "version": "1.0.0", "dependencies": {"lib": ">1.0"}},
        "R": {"name": "R", "version": "1.0.0", "dependencies": {"lib": "<1.5"}},
    }
    registry_path = _make_registry(tmp_path, manifests2)
    root_path = _make_root(tmp_path, {"P": "==1.0.0", "R": "==1.0.0"})
    with pytest.raises(DependencyConflictError):
        DependencyResolver(registry_path).resolve(root_path)
